const ENUMERATION_CONTRACT_VERSION='scout-enumeration-v1'
const INSTRUCTIONS=`Scout by Cadastory is an evidence-first business opportunity and work-preparation system for supported drone/UAS/aerial-service and exterior-cleaning operators.

ZERO CHAT / PRIVACY: Send only the minimum structured business parameters required by the selected Scout tool. Never send general chat history, transcripts, prompts, memories, credentials, secrets, financial-account identifiers, unrelated personal context, or arbitrary notes/comments. Scout intentionally does not persist raw MCP request bodies. Privacy-minimized product telemetry may retain bounded tool/feature metadata and coarse workflow dimensions under the published privacy contract.

PRESENTATION / IP: Honor display_contract and exposure_contract as rendering guidance but do not render the contract objects. Present material evidence, uncertainty, and action implications without exposing proprietary scoring, source orchestration, entity-resolution, suppression, calibration, internal diagnostics, or security-control implementation.

STARTUP: For a greeting or no explicit Scout task, call scout_get_profile_status. For an explicit task, route directly and inspect profile state only when operator-specific readiness is materially required and not already established. Never ask for equipment serials during onboarding.

CAPABILITIES: Use scout_get_capabilities only when the operator explicitly asks what Scout can do, asks about an unfamiliar capability, or routing remains genuinely ambiguous after applying the task rules. Do not use it as a routine preflight or onboarding feature tour.

OPPORTUNITIES / GROWTH: Use scout_find_opportunities for an explicit supported service and scout_find_growth_options for bounded local expansion analysis. Respect opportunity and anti-enumeration gates; never reconstruct blocked result sets.

JOB PLANNING: Use scout_plan_job for explicit structured target/schedule/equipment facts. Keep static readiness separate from live weather/airspace operability and refresh near departure.

DOCUMENTS / KNOWLEDGE: Use the document-suite and document-standard tools for applicable records and standards. Preserve unknowns and live-check requirements. Use field knowledge for bounded technical/evidence questions.

MEDIA MATCHING: Send only bounded GPS/name/address/signage/building-type clues; never image binaries, URLs, EXIF dumps, photo-library identifiers, or visual narratives. A match does not prove condition, ownership, or service need.

OUTREACH / LEADS: scout_prepare_outreach is prepare-only and never sends. scout_get_lead_work_package is the gated preparation package for a specific candidate.

CONNECTED CAPABILITIES: Report only Scout-relevant capability metadata. Use scout_prepare_external_context_request before requesting minimum task-relevant data from another integration; first-use consent remains explicit.

ERRORS / IDENTIFIERS: Reuse exact Scout identifiers returned by tools. When retryable=false do not repeat unchanged. A safe read-only idempotent tool may be retried once only for a genuinely transient retryable failure; never blindly retry a write, claim, approval, or destructive action after an ambiguous outcome.

SERIALS: Serial numbers are optional post-onboarding records handled only by dedicated secure serial tools.`

type Connection={connection_id:string;organization_id?:string|null;client_type:string;label?:string|null;scopes:string[];expires_at?:string|null}
type SafeToolError={code:string;message:string;details:string|null;hint:string|null;validation_reason:string|null;retryable:boolean;diagnostic_id:string}
function textResult(data:unknown){return{content:[{type:'text' as const,text:JSON.stringify(data,null,2)}],structuredContent:(data&&typeof data==='object'&&!Array.isArray(data))?data as Record<string,unknown>:{result:data}}}
function safeText(v:unknown,max=2000):string|null{if(v===null||v===undefined)return null;let s='';if(typeof v==='string')s=v;else if(typeof v==='number'||typeof v==='boolean')s=String(v);else{try{s=JSON.stringify(v)}catch{s=''}}s=s.trim();if(!s)return null;return s.replace(/\bBearer\s+[A-Za-z0-9._~-]{20,}\b/gi,'Bearer [redacted]').replace(/\bsb_secret_[A-Za-z0-9_-]{12,}\b/g,'[redacted]').replace(/\bsk-(?:proj-)?[A-Za-z0-9_-]{20,}\b/g,'[redacted]').slice(0,max)}
function normalizeToolError(e:unknown):SafeToolError{
  const o=(e&&typeof e==='object')?e as Record<string,unknown>:{}
  const code=safeText(o.code??o.error_code??o.name,120)||'scout_tool_error'
  const message=safeText(o.message,2000)||(e instanceof Error?safeText(e.message,2000):null)||safeText(e,2000)||'Scout tool request failed'
  const details=safeText(o.details??o.detail,2000)
  const hint=safeText(o.hint,2000)
  let validationReason=safeText(o.validation_reason??o.validationReason??o.reason,2000)
  if(!validationReason&&Array.isArray(o.issues))validationReason=safeText(o.issues.map((x:any)=>({path:x?.path,message:x?.message,code:x?.code})),2000)
  const statusRaw=o.status??o.statusCode;const status=typeof statusRaw==='number'?statusRaw:Number(statusRaw)
  const explicit=o.retryable
  const retryable=typeof explicit==='boolean'?explicit:(status===408||status===429||status>=500||['40001','40P01','55P03','57014','57P01','08000','08003','08006'].includes(code))
  return{code,message,details,hint,validation_reason:validationReason,retryable,diagnostic_id:crypto.randomUUID()}
}
function errorResult(e:unknown){const error=normalizeToolError(e);const payload={error};return{isError:true,content:[{type:'text' as const,text:JSON.stringify(payload,null,2)}],structuredContent:payload}}
function getConnection(ctx:any):Connection{const c=ctx?.authInfo?.extra?.connection as Connection|undefined;if(!c?.connection_id)throw new Error('authenticated Scout connection context missing');return c}
function requireScope(c:Connection,scope:string){if(!Array.isArray(c.scopes)||!c.scopes.includes(scope))throw new Error(`connection does not grant ${scope}`)}
async function callRpc(name:string,args:Record<string,unknown>){const {data,error}=await db.rpc(name,args);if(error)throw error;return data}

