function normKey(k:string){return k.trim().toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'')}
function looksLikeSecret(s:string){return /-----BEGIN [A-Z ]*PRIVATE KEY-----/.test(s)||/\bsb_secret_[A-Za-z0-9_-]{12,}\b/.test(s)||/\bsk-(?:proj-)?[A-Za-z0-9_-]{20,}\b/.test(s)||/\bgh[pousr]_[A-Za-z0-9]{20,}\b/.test(s)||/\bxox[baprs]-[A-Za-z0-9-]{10,}\b/.test(s)||/\bBearer\s+[A-Za-z0-9._~-]{20,}\b/i.test(s)||/\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b/.test(s)}
function looksLikeChatDump(s:string){if(s.length<1000)return false;const markers=s.match(/(?:^|\n)\s*(?:user|assistant|human|system|developer)\s*:/gim);return(markers?.length||0)>=3}
function inspectValue(v:unknown,tool:string,flags:Set<string>,depth=0,path:string[]=[]){if(depth>10){flags.add('payload_too_deep');return}if(typeof v==='string'){const last=path[path.length-1]||'';const serialException=tool==='scout_store_equipment_serial'&&normKey(last)==='serial_number';if(!serialException&&/^\d{3}-\d{2}-\d{4}$/.test(v.trim()))flags.add('ssn_like_value');if(looksLikeSecret(v))flags.add('secret_like_value');if(looksLikeChatDump(v))flags.add('chat_transcript_like_value');return}if(Array.isArray(v)){for(const x of v)inspectValue(x,tool,flags,depth+1,path);return}if(v&&typeof v==='object')for(const[k,x]of Object.entries(v as Record<string,unknown>)){const nk=normKey(k);const serialException=tool==='scout_store_equipment_serial'&&nk==='serial_number';if(!serialException&&forbiddenKeys.has(nk))flags.add(`forbidden_key:${nk}`);inspectValue(x,tool,flags,depth+1,[...path,k])}}
type Preflight={ok:boolean;status:number;toolName:string|null;argumentKeys:string[];flags:string[];requestId:string|null;reason?:string}
function preflight(raw:string,connection:Connection):Preflight{if(!raw)return{ok:true,status:200,toolName:null,argumentKeys:[],flags:[],requestId:null};let parsed:any;try{parsed=JSON.parse(raw)}catch{return{ok:false,status:400,toolName:null,argumentKeys:[],flags:['invalid_json'],requestId:null,reason:'invalid JSON-RPC payload'}};const items=Array.isArray(parsed)?parsed:[parsed];const flags=new Set<string>();const keys=new Set<string>();let toolName:string|null=null;let requestId:string|null=null;for(const item of items){if(!item||typeof item!=='object')continue;if(item.id!==undefined&&requestId===null)requestId=String(item.id).slice(0,160);if(item.method!=='tools/call')continue;const name=typeof item.params?.name==='string'?item.params.name:'';toolName=toolName?`${toolName},${name}`.slice(0,500):name;const args=(item.params?.arguments&&typeof item.params.arguments==='object'&&!Array.isArray(item.params.arguments))?item.params.arguments:{};Object.keys(args).forEach(k=>keys.add(k));inspectValue(args,name,flags)}if(flags.size)return{ok:false,status:422,toolName,argumentKeys:[...keys].sort(),flags:[...flags],requestId,reason:'Scout rejected fields that are outside the business-only privacy boundary'};return{ok:true,status:200,toolName,argumentKeys:[...keys].sort(),flags:[],requestId}}
async function readBodyLimited(req:Request,max:number){if(!req.body)return'';const reader=req.body.getReader();const chunks:Uint8Array[]=[];let total=0;try{while(true){const{done,value}=await reader.read();if(done)break;if(!value)continue;total+=value.byteLength;if(total>max)throw new Error('request_too_large');chunks.push(value)}}finally{reader.releaseLock()}const merged=new Uint8Array(total);let off=0;for(const c of chunks){merged.set(c,off);off+=c.byteLength}return new TextDecoder().decode(merged)}
async function audit(connection:Connection,pf:Preflight,outcome:string,requestBytes:number,durationMs:number,httpStatus:number){try{await db.rpc('scout_record_agent_request_event',{p_connection_id:connection.connection_id,p_tool_name:pf.toolName,p_protocol_method:'tools/call',p_outcome:outcome,p_request_bytes:requestBytes,p_argument_keys:pf.argumentKeys,p_privacy_flags:pf.flags,p_duration_ms:durationMs,p_http_status:httpStatus,p_request_id:pf.requestId})}catch{}}

