function responseHeaders(h:Headers){h.set('access-control-allow-origin','*');h.set('vary','Origin');h.set('cache-control','no-store, max-age=0');h.set('pragma','no-cache');h.set('referrer-policy','no-referrer');h.set('x-content-type-options','nosniff');h.set('x-scout-privacy',PRIVACY_NOTICE_VERSION);h.set('x-scout-contract',CONTRACT_VERSION);h.set('x-scout-exposure-contract',EXPOSURE_CONTRACT_VERSION);h.set('x-scout-enumeration-contract',ENUMERATION_CONTRACT_VERSION);return h}
Deno.serve(async(req:Request)=>{
  const started=Date.now()
  if(req.method==='OPTIONS')return new Response(null,{status:204,headers:responseHeaders(new Headers({'access-control-allow-headers':'authorization,content-type,mcp-protocol-version,mcp-session-id,x-request-id','access-control-allow-methods':'GET,POST,DELETE,OPTIONS'}))})
  const auth=req.headers.get('authorization')||'';const match=auth.match(/^Bearer\s+(.+)$/i)
  if(!match)return Response.json({error:'missing Scout bearer token'},{status:401,headers:responseHeaders(new Headers())})
  const token=match[1].trim();const {data,error}=await db.rpc('scout_resolve_agent_connection_v4',{p_token:token,p_privacy_contract:CONTRACT_VERSION,p_exposure_contract:EXPOSURE_CONTRACT_VERSION,p_enumeration_contract:ENUMERATION_CONTRACT_VERSION})
  if(error||!data)return Response.json({error:'invalid or expired Scout connection'},{status:401,headers:responseHeaders(new Headers())})
  const connection=data as Connection
  let raw=''
  try{const declared=Number(req.headers.get('content-length')||0);if(declared>MAX_BODY_BYTES)throw new Error('request_too_large');if(req.method==='POST')raw=await readBodyLimited(req.clone(),MAX_BODY_BYTES)}catch(e){const err=normalizeToolError(e);const pf:Preflight={ok:false,status:413,toolName:null,argumentKeys:[],flags:['request_too_large'],requestId:null,reason:'Scout tool request exceeds the privacy gateway size limit'};await audit(connection,pf,'rejected_privacy',MAX_BODY_BYTES+1,Date.now()-started,413);return Response.json({error:{...err,code:'request_too_large',message:pf.reason,retryable:false}},{status:413,headers:responseHeaders(new Headers())})}
  const requestBytes=new TextEncoder().encode(raw).byteLength;const pf=preflight(raw,connection)
  if(!pf.ok){await audit(connection,pf,'rejected_privacy',requestBytes,Date.now()-started,pf.status);return Response.json({error:{code:pf.status===400?'invalid_json':'privacy_boundary_rejected',message:pf.reason||'Scout request rejected',details:null,hint:null,validation_reason:pf.flags.join(', ')||null,retryable:false,diagnostic_id:crypto.randomUUID()},privacy_notice:PRIVACY_NOTICE_VERSION,contract:CONTRACT_VERSION},{status:pf.status,headers:responseHeaders(new Headers())})}
  const authInfo={token:'scout-connection-token-redacted',clientId:connection.connection_id,scopes:connection.scopes||[],expiresAt:connection.expires_at?Math.floor(new Date(connection.expires_at).getTime()/1000):undefined,extra:{connection}}
  try{const response=await mcp.fetch(req,{authInfo});await audit(connection,pf,response.status>=500?'error':'allowed',requestBytes,Date.now()-started,response.status);return new Response(response.body,{status:response.status,statusText:response.statusText,headers:responseHeaders(new Headers(response.headers))})}catch(e){await audit(connection,pf,'error',requestBytes,Date.now()-started,500);return Response.json({error:normalizeToolError(e)},{status:500,headers:responseHeaders(new Headers())})}
})
